const meses = {
  enero: 1, febrero: 2, marzo: 3,
  abril: 4, mayo: 5, junio: 6,
  julio: 7, agosto: 8, setiembre: 9,
  septiembre: 9, octubre: 10,
  noviembre: 11, diciembre: 12
};

// Obtener fecha solicitada en WF1 o WF0.
function obtenerFecha() {
  const opciones = [
    () => $('Code - preparar fecha MIDAGRI1')
      .first().json.fecha_objetivo,

    () => $('Loop Over Items')
      .item.json.fecha_objetivo
  ];

  for (const opcion of opciones) {
    try {
      const fecha = String(opcion() ?? '')
        .slice(0, 10);

      if (/^\d{4}-\d{2}-\d{2}$/.test(fecha)) {
        return fecha;
      }
    } catch (e) {}
  }

  throw new Error(
    'No se encontro fecha_objetivo de WF0 o WF1'
  );
}

const fechaObjetivo = obtenerFecha();

// Formato:
// Producto | 4 volumenes | unidad |
// equivalencia kg | 3 precios.

const num = String.raw`\d+(?:[.,]\d+)?`;
const celda = String.raw`(?:${num}|:|\.{3})`;

const unidad = String.raw`(Kilogramo|Bandeja|Caj[oó]n|Caja|Jaba|Bolsa|Ciento|Unidad|Saco|Paquete|Atado|Mano)`;

const patron = new RegExp(
  String.raw`^(.+?)\s+` +
  String.raw`(${celda})\s+` +
  String.raw`(${celda})\s+` +
  String.raw`(${celda})\s+` +
  String.raw`(${celda})\s+` +
  unidad + String.raw`\s+` +
  String.raw`(${num})\s+` +
  String.raw`(${celda})\s+` +
  String.raw`(${celda})\s+` +
  String.raw`(${celda})\s*$`,
  'i'
);

function numero(valor) {
  const texto = String(valor ?? '').trim();

  // Valores no disponibles en el boletin.
  if (
    texto === ':' ||
    texto === '...' ||
    texto === ''
  ) {
    return null;
  }

  const n = Number(texto.replace(',', '.'));

  return Number.isFinite(n) ? n : null;
}

function extraerFila(texto) {
  const m = texto.match(patron);

  if (!m) return null;


let producto = m[1]
  .replace(/\s+/g, ' ')
  .trim();

producto = producto.replace(
  /^Ayer\s+Hoy\s+[ÚU]ltimos\s+7\s+d[ií]as\s+/i,
  ''
);


// Eliminar encabezado de la tabla
// que se une accidentalmente a Aguaje.
producto = producto.replace(
  /^Frutas\s+(?=Aguaje$)/i,
  ''
);


  if (
    producto.length < 2 ||
    producto.length > 90 ||
    /BOLET[IÍ]N|PRODUCTOS|PRECIO|MASA|FUENTE|ELABORACI[OÓ]N|MMF2|MIDAGRI|DGESEP|lunes|martes|mi[eé]rcoles|jueves|viernes|s[aá]bado|domingo/i
      .test(producto)
  ) {
    return null;
  }

  return {
    producto,
    volumen_ayer_t: numero(m[2]),
    volumen_t: numero(m[3]),
    volumen_promedio_7d_t: numero(m[4]),
    volumen_promedio_4d_t: numero(m[5]),

    unidad: m[6],
    equivalencia_kg: numero(m[7]),

    precio_ayer: numero(m[8]),
    precio: numero(m[9]),
    precio_promedio_7d: numero(m[10])
  };
}

for (const item of items) {
  const texto = String(item.json.text ?? '');

  if (!texto.trim()) {
    throw new Error(
      'Extract from File1 no entrego texto'
    );
  }

  // Validar el tipo de boletin.
  if (
    !/MMF2\s*-\s*Abastecimiento|MERCADO MAYORISTA\s+DE FRUTAS/i.test(texto) ||
    !/Masa de ingreso\s*\(t\)/i.test(texto)
  ) {
    throw new Error(
      'El documento no corresponde al boletin independiente MMF2'
    );
  }

  // Extraer fecha de la cabecera.
  const cabecera = texto.match(
    /\b(\d{1,2})\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|setiembre|septiembre|octubre|noviembre|diciembre)\s+de\s+(20\d{2})\b/i
  );

  if (!cabecera) {
    throw new Error(
      'No se pudo verificar la fecha del PDF'
    );
  }

  const fechaPDF =
    `${cabecera[3]}-` +
    `${String(meses[cabecera[2].toLowerCase()]).padStart(2, '0')}-` +
    `${String(cabecera[1]).padStart(2, '0')}`;

  if (fechaPDF !== fechaObjetivo) {
    throw new Error(
      `Fecha del PDF: ${fechaPDF}. ` +
      `Fecha solicitada: ${fechaObjetivo}`
    );
  }

  const lineas = texto
    .split(/\r?\n/)
    .map(x => x.replace(/\s+/g, ' ').trim())
    .filter(Boolean);

  // Procesar filas completas o divididas
  // en varias lineas del PDF.
  for (let i = 0; i < lineas.length; i++) {
    let encontrado = null;
    let consumir = 0;

    for (
      let k = 1;
      k <= Math.min(12, lineas.length - i);
      k++
    ) {
      const candidato = lineas
        .slice(i, i + k)
        .join(' ');

      const fila = extraerFila(candidato);

      if (fila) {
        encontrado = fila;
        consumir = k;
        break;
      }

      if (candidato.length > 190) break;
    }

    if (!encontrado) continue;

    i += consumir - 1;

    const r = encontrado;
    const clave =
      `${fechaPDF}|${r.producto.toUpperCase()}`;

    if (vistos.has(clave)) continue;
    vistos.add(clave);

    if (
      r.equivalencia_kg === null ||
      r.equivalencia_kg <= 0
    ) {
      errores.push(
        'Equivalencia invalida: ' + r.producto
      );
      continue;
    }

    if (r.precio === null || r.precio <= 0) {
      errores.push(
        'Sin precio de hoy: ' + r.producto
      );
      continue;
    }

    resultados.push({
      json: {
        fecha: fechaPDF,
        codigo_cnpa: null,

        producto: r.producto,
        mercado: 'MMF2',

        unidad: r.unidad,
        equivalencia_kg: r.equivalencia_kg,

        precio: r.precio,
        precio_ayer: r.precio_ayer,
        precio_promedio_7d: r.precio_promedio_7d,

        volumen_t: r.volumen_t,
        volumen_kg:
          r.volumen_t === null
            ? null
            : r.volumen_t * 1000,

        volumen_ayer_t: r.volumen_ayer_t,
        volumen_promedio_7d_t:
          r.volumen_promedio_7d_t,
        volumen_promedio_4d_t:
          r.volumen_promedio_4d_t,

        fuente: 'MIDAGRI',
        formato_origen: 'MMF2 independiente',
        tipo_prueba: 'parser_mmf2_ingreso'
      }
    });
  }
}

